using System.Runtime.InteropServices;

namespace CatalogSvc;

public readonly record struct ProductInfo(string Category, decimal Price);

public class ProductCatalog
{
    private readonly Dictionary<string, ProductInfo> _products = new(StringComparer.OrdinalIgnoreCase);

    // Reverse index: category -> set of product codes
    private readonly Dictionary<string, List<string>> _productsByCategory = new(StringComparer.OrdinalIgnoreCase);

    public void AddProduct(string code, string category, decimal price)
    {
        ref var entry = ref CollectionsMarshal.GetValueRefOrAddDefault(_products, code, out bool exists);
        var oldCategory = exists ? entry.Category : null;
        entry = new ProductInfo(category, price);

        if (exists && oldCategory is not null
            && !oldCategory.Equals(category, StringComparison.OrdinalIgnoreCase))
        {
            // Remove from old category index
            if (_productsByCategory.TryGetValue(oldCategory, out var oldList))
                oldList.Remove(code);
        }

        ref var list = ref CollectionsMarshal.GetValueRefOrAddDefault(_productsByCategory, category, out bool categoryExists);
        if (!categoryExists || list is null)
        {
            list = new List<string> { code };
        }
        else if (!exists || oldCategory is null
                 || !oldCategory.Equals(category, StringComparison.OrdinalIgnoreCase))
        {
            list.Add(code);
        }
    }

    public string? GetCategory(string code)
        => _products.TryGetValue(code, out var info) ? info.Category : null;

    public decimal GetTotalPrice(IEnumerable<string> codes)
    {
        decimal total = 0m;
        foreach (var code in codes)
        {
            if (_products.TryGetValue(code, out var info))
                total += info.Price;
        }
        return total;
    }

    public List<string> GetProductsByCategory(string category)
    {
        if (_productsByCategory.TryGetValue(category, out var list))
            return new List<string>(list);
        return new List<string>();
    }
}

